      "content": "{\n  \"name\": \"dock-spreadsheet\",\n  \"version\": \"0.1.0\",\n  \"description\": \"Read-only XLSX, XLS, ODS, CSV and TSV viewer for the DSH dock workbench\",\n  \"keywords\": [\"deepseek-harness\", \"dsh\", \"dock\", \"spreadsheet\", \"xlsx\", \"csv\", \"viewer\"],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AKS1st/dock-spreadsheet.git\"\n  },\n  \"homepage\": \"https://github.com/AKS1st/dock-spreadsheet#readme\",\n  \"bugs\": \"https://github.com/AKS1st/dock-spreadsheet/issues\",\n  \"publishConfig\": { \"registry\": \"https://registry.npmjs.org/\" },\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"assets\",\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"scripts\": {\n    \"check\": \"node scripts/embed-css.mjs && tsc -p tsconfig.json --noEmit --pretty false\",\n    \"build\": \"node scripts/embed-css.mjs && tsc -p tsconfig.json && tsdown -c tsdown.config.mjs\",\n    \"test\": \"pnpm run build && node --test tests/*.test.mjs\"\n  },\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"peerDependencies\": {\n    \"cordis\": \"^4.0.0-rc.7\",\n    \"dock-base\": \">=0.2.0\",\n    \"dock-files\": \">=0.1.0\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"dock-base\": {\n      \"optional\": true\n    },\n    \"dock-files\": {\n      \"optional\": true\n    },\n    \"react\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"papaparse\": \"^5.7.0\",\n    \"tabulator-tables\": \"^6.3.1\",\n    \"xlsx\": \"https://cdn.sheetjs.com/xlsx-0.20.3/xlsx-0.20.3.tgz\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/papaparse\": \"^5.5.2\",\n    \"@types/react\": \"^18.2.0\",\n    \"@types/react-dom\": \"^18.3.7\",\n    \"@types/tabulator-tables\": \"^6.3.6\",\n    \"cordis\": \"^4.0.0-rc.7\",\n    \"jsdom\": \"^26.1.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^6.0.3\"\n  }\n}\n"
